class Solution:
    def numberOfSequence(self, n: int, sick: List[int]) -> int:
        MOD = 10**9 + 7

        contiguous_sections = []
        for i in range(len(sick) - 1):
            start = sick[i]
            end = sick[i+1]
            if start + 1 < end:
                contiguous_sections.append(end - start - 1)

        if sick[0] != 0:
            contiguous_sections.append(sick[0])

        if sick[-1] != n - 1:
            contiguous_sections.append(n - 1 - sick[-1])

        def factorial(num):
            result = 1
            for i in range(2, num + 1):
                result = (result * i) % MOD
            return result

        total_length = sum(contiguous_sections)
        result = factorial(total_length)

        for length in contiguous_sections:
            result = (result * pow(factorial(length), MOD - 2, MOD)) % MOD

        return result
